import{z as o,x as i,o as A,c as p,q as s,j as t,D as B,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"距离向量","description":"","frontmatter":{"title":"距离向量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distance-vector.md","filePath":"cs/distance-vector.md","lastUpdated":1791063341000}'),d={name:"cs/distance-vector.md"};function D(c,a,m,P,F,h){const r=i("Mermaid");return A(),p("div",null,[a[2]||(a[2]=s('<h1 id="距离向量" tabindex="-1">距离向量 <a class="header-anchor" href="#距离向量" aria-label="Permalink to &quot;距离向量&quot;">​</a></h1><div class="epigraph"><p>每个路由器只告诉邻居：我到各前缀的距离；邻居取最小，像分布式的松弛。</p><footer>—— 据 Ford, Fulkerson 与 Bellman 的最短路松弛；RFC 2453 RIP Version 2 整理</footer></div><p><a href="/cs/ipv6-ndp">上一课</a>假定转发表已在。<a href="/cs/lpm">LPM</a> 只查找不填表。缺口是控制平面的一种：邻居交换「到某前缀多远」，本地做松弛。图课的 <a href="/cs/bellman-ford">Bellman-Ford</a> 已给出边权松弛；本课把它放到路由器上，并点出无穷计数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态配下一跳不能跟故障。距离向量：周期性或触发地，把向量 \\((前缀, 距离)\\) 发给邻居。收到后，经该邻居的距离 = 通告距离 + 链路代价，比现有更好则更新。缺口不是 ICMP，而是这套分布式 BF。RIP 把无穷定为 16，跳数当代价，只适合小域。</p><p>本课不把 RIP 认证头写完。</p><p><span class="marginnote">无穷计数：链路断了，A 与 B 互相以为对方仍通，距离加到无穷。毒性逆转、水平分割是补丁，不是证明消失。</span></p><p><span class="marginnote">术语翻译：距离向量里的「向量」就是一张迷你价目表——每个路由器定期向邻居喊话：「到前缀 P 我这儿距离 3，到前缀 Q 距离 7……」。邻居收到后做一道小学算术：3 加上你到我这条链路的代价，跟我自己表里的数比一比，谁小填谁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化：直连前缀距离 0。通告整个向量（或增量）。失效：超时未刷新则置无穷并通告。与<a href="/cs/spanning-tree">生成树</a>不同：DV 在三层，键是 IP 前缀，允许任意拓扑上的多路径候选，转发仍只装一条或 ECMP。</p>',10)),(A(),t(n,null,{default:B(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E9%82%BB%E5%B1%85%E9%80%9A%E5%91%8A%E5%90%91%E9%87%8F%22%5D%20--%3E%20RELAX%5B%22%E7%BB%8F%E8%AF%A5%E9%82%BB%E5%B1%85%E6%9D%BE%E5%BC%9B%22%5D%0A%20%20RELAX%20--%3E%20TAB%5B%22%E6%9B%B4%E6%96%B0%20LPM%20%E8%A1%A8%22%5D%0A%20%20RELAX%20--%3E%20LOOP%5B%22%E5%9D%8F%E6%B6%88%E6%81%AF%E6%85%A2%3A%20%E6%97%A0%E7%A9%B7%E8%AE%A1%E6%95%B0%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("DV 实现简单，内存只存向量，符合早期线路贵的环境。坏消息慢，是因为没有全局拓扑：断边之后仍可能引用彼此的旧好消息。端到端：路由震荡期间 IP 仍尽力转发，可能环到 TTL 尽，于是 "),e("a",{href:"/cs/icmp"},"ICMP 超时"),E("出现。传输层看见丢包。")],-1)),a[5]||(a[5]=e("p",null,"与进程调度无关：这是路由器进程（或内核协议）之间的消息，可用后课 UDP（RIP 正是如此）。",-1)),(A(),t(n,null,{default:B(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20OK%5B%22A%E2%80%94B%20%E9%93%BE%E8%B7%AF%E6%AD%A3%E5%B8%B8%EF%BC%9AA%20%E7%BB%8F%E7%9B%B4%E8%BF%9E%E5%88%B0%E7%BD%91%20N%20%E8%B7%9D%201%22%5D%20--%3E%20CUT%5B%22%E9%93%BE%E8%B7%AF%E6%96%AD%EF%BC%9AA%20%E6%9C%AC%E5%BA%94%E6%8A%8A%20N%20%E7%BD%AE%E6%97%A0%E7%A9%B7%22%5D%0A%20%20CUT%20--%3E%20HEAR%5B%22A%20%E5%8D%B4%E6%94%B6%E5%88%B0%20B%20%E7%9A%84%E6%97%A7%E9%80%9A%E5%91%8A%EF%BC%9AB%20%E7%BB%8F%20A%20%E5%88%B0%20N%20%E8%B7%9D%202%22%5D%0A%20%20HEAR%20--%3E%20UP1%5B%22A%20%E6%9B%B4%E6%96%B0%EF%BC%9A%E7%BB%8F%20B%20%E8%B7%9D%203%EF%BC%9BB%20%E4%B8%8B%E4%B8%80%E8%BD%AE%E5%AD%A6%E5%88%B0%E8%B7%9D%204%22%5D%0A%20%20UP1%20--%3E%20CLIMB%5B%22%E4%B8%A4%E4%BA%BA%E4%BA%92%E7%9B%B8%E6%8A%84%E4%BD%9C%E4%B8%9A%EF%BC%8C%E6%AF%8F%E8%BD%AE%E5%90%84%20%2B2%EF%BC%9A5%E3%80%817%E3%80%819%E2%80%A6%E2%80%A6%22%5D%0A%20%20CLIMB%20--%3E%20CAP%5B%22RIP%20%E4%B8%8A%E9%99%90%2016%EF%BC%9A%E7%BA%A6%2016%20%E4%B8%AA%E5%91%A8%E6%9C%9F%E5%90%8E%E6%89%8D%E6%89%BF%E8%AE%A4%20N%20%E4%B8%8D%E5%8F%AF%E8%BE%BE%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>这张图回答「无穷计数是怎么滚起来的」：断链后 A 本该宣布距离无穷，但它手里还有 B 的旧好消息——而那条「好消息」当初恰恰是经过 A 学的。两人拿着互相推导出来的旧数继续松弛，每交换一轮距离就涨一截。数字实例：RIP 每 30 秒一轮、上限 16，最坏要 7 分多钟全网才认账，这期间数据包就在两个路由器之间转圈到 TTL 耗尽。</p><p><span class="marginnote">常见误区：初学者容易以为「只要表收敛过，断链后会自动快速收敛到新状态」。距离向量没有全局图，它无法区分「经邻居中转的好消息」和「邻居早就过期的回声」；水平分割、毒性逆转只是挡住最典型的回声路径，环多于两个节点时照样慢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 EIGRP 的 DUAL 写完，不引入路径向量——那是 BGP 用 AS 路径防环。也不把负权当互联网代价：链路代价为正。全局拓扑与更快收敛是下一课链路状态。</p><p>度量若用带宽或延迟，必须保证正且无震荡；RIP 用跳数正是为了简单。触发更新比定期全表更快送出坏消息。</p><p>不等间隔的定时器抖动，用来避免同步通告造成的周期性拥塞。</p><p>后课默认：邻居向量可填表，但环与慢收敛是代价。通告整图、本地跑最短路，下一课链路状态。</p><p><span class="marginnote">直觉类比区分两族协议：距离向量像只靠邻居转述的传言——你从不知道整张地图，只知道「听说离这儿 5 站」；链路状态像人手一份完整地图，各自在本地跑 Dijkstra。传言便宜但会以讹传讹（无穷计数），地图费带宽但收敛有据——这正是下一课的动机。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>距离向量是分布式 Bellman-Ford，填 LPM。</li><li>无穷计数；水平分割只是缓解。</li><li>链路状态用整图对照，下一课。</li><li>出处：Bellman-Ford；RFC 2453；Kurose and Ross。</li></ul>',10))])}const u=o(d,[["render",D]]);export{f as __pageData,u as default};
